-- Assessment questions and their options.
-- Tables: qstn_lst_t, qstn_optn_lst_t
-- Generated by server/scripts/export-sql.mjs from the migrated database. Run the files in numeric order on an empty database.

BEGIN;

CREATE TABLE public.qstn_lst_t (
    qstn_id text NOT NULL,
    college_id text NOT NULL,
    course_id text,
    qstn_type_cd public."QuestionType" NOT NULL,
    stem_tx text NOT NULL,
    explanation_tx text DEFAULT ''::text NOT NULL,
    difficulty_cd public."Difficulty" DEFAULT 'MEDIUM'::public."Difficulty" NOT NULL,
    marks_ct double precision DEFAULT 1 NOT NULL,
    negative_marks_ct double precision DEFAULT 0 NOT NULL,
    answer_key_json jsonb,
    topic_tx text DEFAULT ''::text NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    u_ts timestamp(3) without time zone,
    crte_usr_id text,
    updte_usr_id text,
    a_in smallint DEFAULT 1 NOT NULL,
    d_ts timestamp(3) without time zone,
    cdng_prblm_id text,
    CONSTRAINT qstn_lst_t_a_in_check CHECK ((a_in = ANY (ARRAY[0, 1]))),
    CONSTRAINT qstn_lst_t_marks_check CHECK (((marks_ct > (0)::double precision) AND (negative_marks_ct >= (0)::double precision)))
);

CREATE TABLE public.qstn_optn_lst_t (
    qstn_optn_id text NOT NULL,
    qstn_id text NOT NULL,
    optn_tx text NOT NULL,
    is_correct_in smallint DEFAULT 0 NOT NULL,
    sqnce_id integer DEFAULT 0 NOT NULL,
    i_ts timestamp(3) without time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
    CONSTRAINT qstn_optn_lst_t_correct_check CHECK ((is_correct_in = ANY (ARRAY[0, 1])))
);

ALTER TABLE ONLY public.qstn_lst_t
    ADD CONSTRAINT qstn_lst_t_pkey PRIMARY KEY (qstn_id);

ALTER TABLE ONLY public.qstn_optn_lst_t
    ADD CONSTRAINT qstn_optn_lst_t_pkey PRIMARY KEY (qstn_optn_id);

CREATE INDEX qstn_lst_t_college_id_idx ON public.qstn_lst_t USING btree (college_id);

CREATE INDEX qstn_lst_t_course_id_idx ON public.qstn_lst_t USING btree (course_id);

CREATE INDEX qstn_optn_lst_t_qstn_id_idx ON public.qstn_optn_lst_t USING btree (qstn_id);

CREATE TRIGGER qstn_lst_t_audit_timestamps BEFORE UPDATE ON public.qstn_lst_t FOR EACH ROW EXECUTE FUNCTION public.campus_set_audit_timestamps();

-- Foreign keys
ALTER TABLE ONLY public.qstn_optn_lst_t
    ADD CONSTRAINT qstn_optn_lst_t_qstn_id_fkey FOREIGN KEY (qstn_id) REFERENCES public.qstn_lst_t(qstn_id) ON UPDATE CASCADE ON DELETE CASCADE;

COMMIT;
